repair_driver:
import json,subprocess,time,collections,sys
from pathlib import Path
b=Path('/home/mgsloan/byte-rounding-e2e-20260914')
while True:
 try:
  if 'finished' in json.loads((b/'cloud-primary.json').read_text()):break
 except (FileNotFoundError,json.JSONDecodeError):pass
 time.sleep(5)
for attempt in range(5):
 runs=[b/'cloud-primary.json',*sorted(b.glob('cloud-repair*.json'))]
 subprocess.run(['python3',b/'tools/squatter/summarize-byte-rounding.py',*runs,'--output',b/'summary.json','--audit-output',b/'audit.json'],check=True)
 audit=json.loads((b/'audit.json').read_text()); counts={(r['points'],r['case']):r['blocks'] for r in audit['accepted']}
 missing=collections.defaultdict(list)
 for point in [1,0]:
  for c in json.loads((b/'manifest.json').read_text())['cases']:
   n=3-counts.get((point,c['name']),0)
   if n>0:missing[point,n].append(c['name'])
 if not missing:
  guest=json.loads((b/'guest.json').read_text());guest['proc_stat_after']=Path('/proc/stat').read_text();guest['finished']=time.time();(b/'guest.json').write_text(json.dumps(guest,indent=2)+'\n')
  (b/'complete').write_text('All cases have at least three accepted paired blocks.\n');break
 print('Repairing:',dict(missing),flush=True)
 for (point,n),cases in missing.items():
  subprocess.run(['python3',b/'tools/squatter/benchmark-byte-rounding.py','--output',b,'--end-to-end','--validate-once','--loader','/lib64/ld-linux-x86-64.so.2','--cpu','0','--points',str(point),'--variants','exact,r7,r6,r5,r2,r5_9','--rounds',str(n),'--repeats','3','--cases',','.join(cases),'--tag',f'cloud-repair-{attempt}-p{point}-n{n}'],check=True)
else:sys.exit('Control remained unstable after five repair attempts')
